E \r\n					 synch.container_type IN (\'post\', \'page\') AND posts.ID IS NULL\";i:2;N;}i:40;a:3:{i:0;i:0;i:1;s:38:\"...... 0 rows deleted in 0.000 seconds\";i:2;N;}i:41;a:3:{i:0;i:0;i:1;s:69:\"...... Deleting synch records for posts that have a disallowed status\";i:2;N;}i:42;a:3:{i:0;i:0;i:1;s:238:\"DELETE synch.*\r\n				  FROM\r\n					 wp_mtsblc_synch AS synch\r\n					 LEFT JOIN wp_mtsposts AS posts\r\n					 ON (synch.container_id = posts.ID and synch.container_type = posts.post_type)\r\n				  WHERE\r\n					 posts.post_status NOT IN (\'publish\')\";i:2;N;}i:43;a:3:{i:0;i:0;i:1;s:38:\"...... 0 rows deleted in 0.000 seconds\";i:2;N;}i:44;a:3:{i:0;i:0;i:1;s:41:\"...... Marking changed posts as unsynched\";i:2;N;}i:45;a:3:{i:0;i:0;i:1;s:233:\"UPDATE\r\n					wp_mtsblc_synch AS synch\r\n					JOIN wp_mtsposts AS posts ON (synch.container_id = posts.ID and synch.container_type=posts.post_type)\r\n				  SET \r\n					synched = 0\r\n				  WHERE\r\n					synch.last_synch < posts.post_modified\";i:2;N;}i:46;a:3:{i:0;i:0;i:1;s:38:\"...... 0 rows updated in 0.000 seconds\";i:2;N;}i:47;a:3:{i:0;i:0;i:1;s:43:\"...... Creating synch records for new posts\";i:2;N;}i:48;a:3:{i:0;i:0;i:1;s:409:\"INSERT INTO wp_mtsblc_synch(container_id, container_type, synched)\r\n				  SELECT posts.id, posts.post_type, 0\r\n				  FROM \r\n				    wp_mtsposts AS posts LEFT JOIN wp_mtsblc_synch AS synch\r\n					ON (synch.container_id = posts.ID and synch.container_type=posts.post_type)  \r\n				  WHERE\r\n				  	posts.post_status IN (\'publish\')\r\n	 				AND posts.post_type IN (\'post\', \'page\')\r\n					AND synch.container_id IS NULL\";i:2;N;}i:49;a:3:{i:0;i:0;i:1;s:39:\"...... 0 rows inserted in 0.000 seconds\";i:2;N;}i:50;a:3:{i:0;i:0;i:1;s:27:\"... Notifying module \"page\"\";i:2;N;}i:51;a:3:{i:0;i:0;i:1;s:74:\"...... Skipping \"page\" resyncyh since all post types were already synched.\";i:2;N;}i:52;a:3:{i:0;i:0;i:1;s:38:\"... Notifying module \"youtube-checker\"\";i:2;N;}i:53;a:3:{i:0;i:0;i:1;s: