(8866, 1564612050, 1564612050, 'new', 'wfPluginAbandoned', 50, '13076807dd55e3faf0acd398595611cc', '13076807dd55e3faf0acd398595611cc', 'The Plugin \"Faster Pagination\" appears to be abandoned (updated 28/06/2014, tested to WP 3.9.27).', 'It was last updated 5 years 1 month ago and tested up to WordPress 3.9.27. It may have compatibility problems with the current version of WordPress or unknown security issues. <a href=\"https://www.wordfence.com/help/?query=scan-result-plugin-abandoned\" target=\"_blank\" rel=\"noopener noreferrer\">Get more information.</a>', 'a:19:{s:4:\"name\";s:17:\"Faster Pagination\";s:4:\"slug\";s:17:\"faster-pagination\";s:7:\"version\";s:3:\"1.0\";s:6:\"author\";s:51:\"<a href=\"http://fasterthemes.com/\">FasterThemes</a>\";s:14:\"author_profile\";s:43:\"https://profiles.wordpress.org/fasterthemes\";s:8:\"requires\";s:3:\"2.8\";s:6:\"tested\";s:6:\"3.9.27\";s:12:\"requires_php\";b:0;s:13:\"compatibility\";a:0:{}s:11:\"num_ratings\";i:2;s:15:\"support_threads\";i:0;s:24:\"support_threads_resolved\";i:0;s:12:\"last_updated\";s:21:\"2014-06-28 4:45am GMT\";s:8:\"homepage\";s:24:\"http://fasterthemes.com/\";s:13:\"download_link\";s:60:\"https://downloads.wordpress.org/plugin/faster-pagination.zip\";s:11:\"dateUpdated\";s:10:\"28/06/2014\";s:9:\"abandoned\";b:1;s:10:\"vulnerable\";b:0;s:5:\"wpURL\";s:47:\"https://wordpress.org/plugins/faster-pagination\";}'),
(8893, 1564833854, 1564833854, 'new', 'wfUpgrade', 75, '75b4d5d54debe82ca6000ff15fbd8b55', '75b4d5d54debe82ca6000ff15fbd8b55', 'Your WordPress version is out of date', 'WordPress version 5.2.2 is now available. Please upgrade immediately to get the latest security updates from WordPress.', 'a:2:{s:14:\"currentVersion\";s:5:\"5.1.1\";s:10:\"newVersion\";s:5:\"5.2.2\";}'),
(8894, 1564833854, 1564833854, 'new', 'wfPluginUpgrade', 50, '46253bd9f90a4d165a085e5f666519e3', '46253bd9f90a4d165a085e5f666519e3', 'The Plugin \"AddToAny Share Buttons\" needs an upgrade (1.7.28 -> 1.7.36).', 'You need to upgrade \"AddToAny Share Buttons\" to the newest version to ensure you have any security fixes the developer has released.', 'a:26:{s:8:\"ModuleID\";s:0:\"\";s:14:\"ModuleCategory\";s:0:\"\";s:13:\"ModuleContext\";s:0:\"\";s:14:\"ModuleLazyInit\";s:0:\"\";s:15:\"ModuleClassName\";s:0:\"\";s:14:\"ModulePriority\";s:0:\"\";s:23:\"ModuleCheckerUrlPattern\";s:0:\"\";s:12:\"ModuleHidden\";s:0:\"\";s:18:\"ModuleAlwaysActive\";s:0:\"\";s:17:\"ModuleRequiresPro\";s:0:\"\";s:4:\"Name\";s:22:\"AddToAny Share Buttons\";s:9:\"PluginURI\";s:25:\"https://www.addtoany.com/\";s:7:\"Version\";s:6:\"1.7.28\";s:11:\"Description\";s:210:\"Share buttons for your pages including AddToAny&#8217;s universal sharing button, Facebook, Twitter, Google+, Pinterest, WhatsApp and many more. <cite>By <a href=\"https://www.addtoany.com/\">AddToAny</a>.</cite>\";s:6:\"Author\";s:48:\"<a href=\"https://www.addtoany.com/\">AddToAny</a>\";s:9:\"AuthorURI\";s:25:\"https://www.addtoany.com/\";s:10:\"TextDomain\";s:10:\"add-to-any\";s:10:\"DomainPath\";s:10:\"/languages\";s:7:\"Network\";b:0;s:5:\"Title\";s:62:\"<a href=\"https://www.addtoany.com/\">AddToAny Share Buttons</a>\";s:10:\"AuthorName\";s:8:\"AddToAny\";s:10:\"pluginFile\";s:75:\"/hosting/www/techwinky.com/www/wp-content/plugins/add-to-any/add-to-any.php\";s:10:\"newVersion\";s:6:\"1.7.36\";s:4:\"slug\";s:10:\"add-to-any\";s:5:\"wpURL\";s:40:\"https://wordpress.org/plugins/add-to-any\";s:10:\"vulnerable\";b:0;}'),
(8895, 1564833854, 1564833854, 'new', 'wfPluginUpgrade', 50, 'bca5daf2905d65797da87ce6f2d3477b', 'bca5daf2905d65797da87ce6f2d3477b', 'The Plugin \"Akismet Anti-Spam\" needs an upgrade (4.0.8 -> 4.1.2).', 'You need to upgrade \"Akismet Anti-Spam\" to the newest version to ensure you have any security fixes the developer has released.', 'a:26:{s:8:\"ModuleID\";s:0:\"\";s:14:\"ModuleCategory\";s:0:\"\";s:13:\"ModuleContext\";s:0:\"\";s:14:\"ModuleLazyInit\";s:0:\"\";s:15:\"ModuleClassName\";s:0:\"\";s:14:\"ModulePriority\";s:0:\"\";s:23:\"ModuleCheckerUrlPattern\";s:0:\"\";s:12:\"ModuleHidden\";s:0:\"\";s:18:\"ModuleAlwaysActive\";s:0:\"\";s:17:\"ModuleRequiresPro\";s:0:\"\";s:4:\"Name\";s:17:\"Akismet Anti-Spam\";s:9:\"PluginURI\";s:20:\"https://akismet.com/\";s:7:\"Version\";s:5:\"4.0.8\";s:11:\"Description\";s:363:\"Used by millions, Akismet is quite possibly the best way in the world to <strong>protect your blog from spam</strong>. It keeps your site protected even while you sleep. To get started: activate the Akismet plugin and then go to your Akismet Settings page to set up your API key. <cite>By <a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>.</cite>\";s:6:\"Author\";s:66:\"<a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>\";s:9:\"AuthorURI\";s:41:\"https://automattic.com/wordpress-plugins/\";s:10:\"TextDomain\";s:7:\"akismet\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:5:\"Title\";s:52:\"<a href=\"https://akismet.com/\">Akismet Anti-Spam</a>\";s:10:\"AuthorName\";s:10:\"Automattic\";s:10:\"pluginFile\";s:69:\"/hosting/www/techwinky.com/www/wp-content/plugins/akismet/akismet.php\";s:10:\"newVersion\";s:5:\"4.1.2\";s:4:\"slug\";s:7:\"akismet\";s:5:\"wpURL\";s:37:\"https://wordpress.org/plugins/akismet\";s:10:\"vulnerable\";b:0;}'),
